using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class CitasDeRespuesta
{
    private const int MaximoCitasDeRespaldo = 2;

    private readonly int _apoyoMinimo;

    public CitasDeRespuesta(int apoyoMinimo)
    {
        _apoyoMinimo = apoyoMinimo;
    }

    public IReadOnlyList<Cita> EscritasConApoyo(string texto, IReadOnlyList<SeccionDocumento> entregadas, IReadOnlyCollection<Cita> reglasDeDatos)
    {
        var apoyadas = SeccionesConApoyo(texto, entregadas).Select(CitaDe).ToHashSet();
        return [.. ExtractorCitas.De(texto).Where(cita => apoyadas.Contains(cita) || reglasDeDatos.Contains(cita))];
    }

    public IReadOnlyList<Cita> Respaldo(string texto, IReadOnlyList<SeccionDocumento> entregadas) =>
        [.. SeccionesConApoyo(texto, entregadas).Take(MaximoCitasDeRespaldo).Select(CitaDe)];

    private IEnumerable<SeccionDocumento> SeccionesConApoyo(string texto, IReadOnlyList<SeccionDocumento> entregadas)
    {
        var raicesDeLaRespuesta = RaicesDeContenido.DeApoyo(ExtractorCitas.SinCitas(texto)).ToHashSet(StringComparer.Ordinal);
        return entregadas.Where(seccion => RaicesDeContenido.DeApoyo($"{seccion.Titulo} {seccion.Texto}").Count(raicesDeLaRespuesta.Contains) >= _apoyoMinimo);
    }

    private static Cita CitaDe(SeccionDocumento seccion) => new(seccion.Documento, seccion.Seccion);
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Conocimiento;

public static class RaicesDeContenido
{
    private const int LongitudDeRaiz = 4;

    private static readonly HashSet<string> PalabrasVacias = new(StringComparer.Ordinal)
    {
        "cual", "cuales", "como", "cuando", "donde", "quien", "cuanto", "cuantos", "cuanta", "cuantas",
        "puedo", "tengo", "tiene", "tienen", "sobre", "para", "unos", "unas", "pero", "esta", "este", "esto",
        "dice", "dicen", "hacer", "hace", "debe", "puede", "pueden", "estoy", "estan", "dime", "dame", "muestra"
    };

    private static readonly HashSet<string> PalabrasGenericasDelCorpus = new(StringComparer.Ordinal)
    {
        "reglamento", "reglamentos", "documento", "documentos", "articulo", "articulos", "seccion", "secciones",
        "capitulo", "corporacion", "horizonte"
    };

    public static IEnumerable<string> De(string texto) =>
        NormalizadorTexto.Normalizar(texto)
            .Split(' ', StringSplitOptions.RemoveEmptyEntries)
            .Where(EsPalabraDeContenido)
            .Select(palabra => palabra[..LongitudDeRaiz])
            .Distinct(StringComparer.Ordinal);

    public static IReadOnlyCollection<string> DeApoyo(string texto) =>
        [.. De(texto).Concat(RaicesNumericas.De(texto))];

    private static bool EsPalabraDeContenido(string palabra) =>
        palabra.Length >= LongitudDeRaiz
        && !PalabrasVacias.Contains(palabra)
        && !PalabrasGenericasDelCorpus.Contains(palabra);
}
17:- **Bloque "Reglas aplicadas"** (D-29, D-31): el resumen de COMP-07 y cada resultado de una herramienta de datos terminan con la línea "Reglas aplicadas a estos datos: `documento` · `sección`; …", calculada por `Core` a partir de los datos leídos. **Orden fijo** (v1.8): se recorren estas 11 entradas en este orden, se incluye cada una cuya condición se cumple y se omiten las repetidas (queda la primera aparición): 1) notas leídas → `evaluacion_y_calificaciones.md · Sección 3`; 2) notas leídas → `evaluacion_y_calificaciones.md · Sección 4`; 3) asistencia leída → `reglamento_academico_2025.md · Artículo 11`; 4) notas leídas → `bienestar_y_becas.md · Sección 3.1`; y, según el estado de las asignaturas leídas (también en la herramienta de programa del coordinador, que no aporta las entradas 1 a 4): 5) alguna perdida → `Artículo 5`; 6) alguna perdida → `Artículo 6`; 7) alguna perdida por inasistencia → `Artículo 7`; 8) alguna perdida por inasistencia → `Artículo 11`; 9) prueba académica → `Artículo 20`; 10) asistencia sin registro → `Artículo 12`; 11) alguna sin definitiva → `evaluacion_y_calificaciones.md · Sección 3`. El **bloque de la petición** aplica el mismo orden a la unión de los datos leídos en ella (resumen y herramientas). Hasta la v1.7 la entrada 4 iba antes de la 3. El bloque que recibe el LLM conserva este orden fijo; solo la elección de las citas de COMP-02 (2) lo reordena por relevancia (entrada siguiente). Si en la petición se leyeron datos, una cita escrita a una sección de ese bloque se conserva aunque la sección no se haya recuperado ni comparta raíces con la respuesta. Ejemplo: para `COORD-02`, la herramienta de programa lee EST-004, EST-005 y EST-006; Valentina Castro tiene asignaturas perdidas (Microeconomía 1.8 y Estadística 2.3) y está en prueba académica (2.65), y Estadística de EST-006 no tiene definitiva, así que el bloque es [`Artículo 5`, `Artículo 6`, `Artículo 20`, `evaluacion_y_calificaciones.md · Sección 3`] (entradas 5, 6, 9 y 11). Sin lectura de datos no hay bloque ni excepción. El índice **no contiene** el reglamento 2023 ni el Anexo de bienestar, así que una cita a ellos se descarta (SEG-10a).
18:- **Citas de las reglas aplicadas** (COMP-02 (2), D-31): si se leyeron datos (COMP-04 en `true`) y la respuesta no es una negativa, COMP-03 ni `TEXTO_NO_VERIFICABLE`, se agregan las 3 primeras secciones del bloque de la petición **ordenadas por relevancia respecto de la pregunta** (v1.9), sin repetir las escritas válidas. **Orden por relevancia:** sea `R` el conjunto de raíces de contenido distintas de la pregunta (las mismas del umbral de COMP-03 (1): solo raíces de palabras, sin raíces numéricas); la relevancia de cada sección del bloque es el número de raíces de `R` que están entre las raíces de la sección (título y texto, definición de "Raíz de contenido"); las secciones se ordenan de mayor a menor relevancia, el orden fijo del bloque desempata (orden estable), se toman las 3 primeras y después se omiten las que ya están entre las escritas válidas (no se reemplazan por la 4.ª). Con `r = 0` todas valen 0 y queda el orden fijo. El orden nunca agrega una sección que no esté en el bloque. Raíces de las secciones usadas (palabras, sin cifras): `Sección 3` {`nota`, `defi`, `asig`, `prom`, `tres`, `cort`, `segu`, `peso`, `redo`, `cifr`, `deci`, `haci`, `arri`, `ejem`, `qued`, `mien`, `cali`, `estu`, `cons`, `acum`}; `Sección 4` {`prom`, `pond`, `peri`, `calc`, `nota`, `defi`, `redo`, `cred`, `cada`, `asig`, `suma`, `resu`, `expr`, `cifr`, `deci`, `mism`, `crit`, `perd`, `inas`, `cuen`, `entr`}; `Artículo 11` {`perd`, `inas`, `estu`, `falt`, `clas`, `prog`, `asig`, `pier`, `nota`, `defi`, `impo`, `obte`, `cort`}; `bienestar_y_becas.md · Sección 3.1` {`beca`, `rend`, `acad`, `desc`, `matr`, `peri`, `sigu`, `requ`, `prom`, `pond`, `igua`, `supe`, `ning`, `asig`, `perd`, `incl`, `inas`, `habe`, `meno`, `cred`}; `Artículo 5` {`nota`, `mini`, `asig`, `apru`, `defi`, `igua`, `supe`, `esca`}; `Artículo 6` {`habi`, `estu`, `repr`, `asig`, `nota`, `defi`, `igua`, `supe`, `podr`, `pres`, `exam`, `siem`, `haya`, `perd`, `inas`, `reem`}; `Artículo 20` {`prue`, `acad`, `qued`, `estu`, `cuyo`, `prom`, `pond`, `peri`, `infe`}. Cálculo con §11.4: <br>• `EST-001` (resumen de COMP-07 con notas y asistencia): todas aprobadas (4.5, 4.8, 4.1 y 4.0 ≥ 3.0), sin pérdida por inasistencia (1 × 100 ≤ 15 × 64, 0, 2 × 100 = 200 ≤ 720, 1 × 100 = 100 ≤ 480), promedio 4.39 ≥ 3.0, sin nulos → bloque [Sección 3, Sección 4, Artículo 11, `bienestar_y_becas.md · Sección 3.1`]. Q10 #2 "¿Cuál es mi promedio ponderado del periodo?" → `R` = {`prom`, `pond`, `peri`} (`cual` es palabra vacía; `mi` y `del` tienen menos de 4 caracteres); relevancia: Sección 3 = 1 (`prom`), Sección 4 = 3, Artículo 11 = 0, Sección 3.1 = 3 → orden [Sección 4 (3), Sección 3.1 (3; empata con la Sección 4 y va después por el orden fijo), Sección 3 (1), Artículo 11 (0)] → citas [`evaluacion_y_calificaciones.md · Sección 4`, `bienestar_y_becas.md · Sección 3.1`, `evaluacion_y_calificaciones.md · Sección 3`]. Q10 #3 "¿Cuántas faltas tengo en Bases de Datos?" → `R` = {`falt`, `base`, `dato`}; relevancia: Sección 3 = 0, Sección 4 = 0, Artículo 11 = 1 (`falt`, por "falte"), Sección 3.1 = 0 → citas [`reglamento_academico_2025.md · Artículo 11`, `evaluacion_y_calificaciones.md · Sección 3`, `evaluacion_y_calificaciones.md · Sección 4`]. <br>• `EST-004` (Q10 #5 "¿Qué nota definitiva tengo en Contabilidad?"): 3.9, 3.3, 4.0 y 4.5 ≥ 3.0; faltas 0/48, 2/48, 3/64 (300 ≤ 960) y 1/32; promedio 3.88; sin nulos → el mismo bloque de 4; `R` = {`nota`, `defi`, `cont`}; relevancia: Sección 3 = 2, Sección 4 = 2, Artículo 11 = 2 (`nota` y `defi`; ninguna contiene `cont`: "consultar" da `cons`), Sección 3.1 = 0 → empate a 2 resuelto por el orden fijo → citas [`evaluacion_y_calificaciones.md · Sección 3`, `evaluacion_y_calificaciones.md · Sección 4`, `reglamento_academico_2025.md · Artículo 11`]. <br>• `COORD-02` (Q10 #6 "¿Qué estudiantes de mi programa tienen alguna asignatura perdida?", herramienta de programa): `EST-005` con Microeconomía 1.8 y Estadística 2.3 perdidas (< 3.0), sin pérdida por inasistencia (4/48, 5/48, 6/64 y 2/32: 400 ≤ 720, 500 ≤ 720, 600 ≤ 960, 200 ≤ 480) y en prueba académica (2.65 < 3.0); `EST-006` con Estadística sin definitiva → bloque [Artículo 5, Artículo 6, Artículo 20, Sección 3]; `R` = {`estu`, `prog`, `algu`, `asig`, `perd`}; relevancia: Artículo 5 = 1 (`asig`), Artículo 6 = 3 (`estu`, `asig`, `perd`), Artículo 20 = 1 (`estu`), Sección 3 = 2 (`asig`, `estu`) → orden [Artículo 6, Sección 3, Artículo 5 (1; empata con el Artículo 20 y va antes por el orden fijo), Artículo 20] → citas [`reglamento_academico_2025.md · Artículo 6`, `evaluacion_y_calificaciones.md · Sección 3`, `reglamento_academico_2025.md · Artículo 5`]. <br>• `EST-005` (ESC-023 "¿Estoy en prueba académica?", resumen de COMP-07): Contabilidad 3.2·0.3 + 3.0·0.3 + 3.3·0.4 = 3.18 → 3.2, Microeconomía 1.9·0.3 + 1.6·0.3 + 1.9·0.4 = 1.81 → 1.8, Estadística 2.4·0.3 + 2.2·0.3 + 2.3·0.4 = 2.30 → 2.3, Comunicación Oral y Escrita 3.8·0.3 + 3.5·0.3 + 3.9·0.4 = 3.75 → 3.8; promedio (3.2·3 + 1.8·3 + 2.3·4 + 3.8·2) / 12 = 31.8 / 12 = 2.65 < 3.0; sin pérdida por inasistencia ni nulos → bloque [Sección 3, Sección 4, Artículo 11, Sección 3.1, Artículo 5, Artículo 6, Artículo 20] (entradas 1–6 y 9); `R` = {`prue`, `acad`} (`estoy` es palabra vacía); relevancia: Artículo 20 = 2, Sección 3.1 = 1 (`acad`, por "académico" en el título), las demás 0 ("acumulada" da `acum`) → citas [`reglamento_academico_2025.md · Artículo 20`, `bienestar_y_becas.md · Sección 3.1`, `evaluacion_y_calificaciones.md · Sección 3`]. Con el orden fijo de la v1.8 eran [Sección 3, Sección 4, Artículo 11], sin el `Artículo 20`. <br>• `EST-002` (resumen): perdida, perdida por inasistencia y prueba académica → bloque [Sección 3, Sección 4, Artículo 11, Sección 3.1, Artículo 5, Artículo 6, Artículo 7, Artículo 20]; con `r = 0` o sin raíces compartidas → citas [Sección 3, Sección 4, Artículo 11].

